Definition SP_ARROW_STACK : Z := 16.

Definition sp_arrow_post (ra sp gp tp s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (px lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz px) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp).

Definition sp_arrow_stmt (pc : Z) : Prop :=
  forall (A px lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  ro_cells bsegs m A [C8 (wz px)] ->
  0 <= px < 2^64 -> px <> 0 ->
  stk bsegs m lo (bv_unsigned sp) -> lo + SP_ARROW_STACK <= bv_unsigned sp -> aceil <= lo ->
  (bv_unsigned sp <= A \/ A + 8 <= lo) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv bsegs m ->
  ACONST m -> accessible m A 8 -> A mod 8 = 0 ->                                      (* [comment removed for export] *)
  evt bsegs (sp_arrow_post ra sp gp tp s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc px lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz A) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m (seg_rom bsegs)).
