Definition ANYEX_FN_STACK : Z := 16.

Definition anyex_fn_copy_post (ra sp gp tp s0 s1 a0 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (D ioc lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 a3 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (D, D + 8); (D + 32, D + 40)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' D [C8 (wz ioc)]
    /\ rw_cells bsegs m' (D + 32) [C8 (wz D)].

Definition anyex_fn_copy_stmt (pc : Z) : Prop :=
  forall (D S ioc lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (j0 j4 : list byte),
  ro_cells bsegs m S [C8 (wz ioc)] ->
  rw_cells bsegs m D [CB 8 j0] -> rw_cells bsegs m (D + 32) [CB 8 j4] ->
  (S + 8 <= D \/ D + 8 <= S) -> (S + 8 <= D + 32 \/ D + 40 <= S) ->
  0 <= ioc < 2^64 ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  stk bsegs m lo (bv_unsigned sp) -> lo + ANYEX_FN_STACK <= bv_unsigned sp -> aceil <= lo ->
  (bv_unsigned sp <= S \/ S + 8 <= lo) -> (bv_unsigned sp <= D \/ D + 40 <= lo) ->
  bv_unsigned ra mod 2 = 0 ->
  ACONST m -> accessible m S 8 -> S mod 8 = 0 -> accessible m D 40 -> D mod 8 = 0 -> oloc D 40 ->
  evt bsegs (anyex_fn_copy_post ra sp gp tp s0 s1 (wz D) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc D ioc lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz D) (wz S) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m (seg_rom bsegs)).

